// Append the customer's utterance and build the Claude messages array.
const speech = ($('Webhook Gather').item.json.body.SpeechResult || '').trim();
const row = $input.item.json;
const turns = Array.isArray(row.turns) ? row.turns : [];
if (speech) turns.push({ role: 'user', text: speech, ts: Date.now() });

// Build messages; first message MUST be role 'user'.
let messages = turns.filter(t => t.text).map(t => ({ role: t.role, content: t.text }));
while (messages.length && messages[0].role === 'assistant') messages.shift();
if (!messages.length) messages = [{ role: 'user', content: '(call connected — greet the customer)' }];

return [{ json: { call_id: $('Webhook Gather').item.json.query.call_id, turns, messages } }];

const reply = (($input.item.json.content || []).find(b => b.type === 'text') || {}).text || "I'm sorry, could you say that again?";
const prev = $('Append + Build Messages').item.json;
const turns = prev.turns;
turns.push({ role: 'assistant', text: reply, ts: Date.now() });
const farewell = /(thank you for your time|have a great day|take care|goodbye|we'll be in touch)/i.test(reply);
return [{ json: { call_id: prev.call_id, reply, turns, hangup: farewell } }];
